export const celsius2fahrenheit = (c: number) => { 
    return 9.0/5.0 * c + 32;
};
export const fahrenheit2celsius = (f: number) => {
    return (f-32) * 5.0 / 9.0;
};
export const getIndexBySortDescending = (d: number[]) => {
    const indices = new Array(d.length);
    for (let i = 0; i < d.length; ++i) { indices[i] = i; }
    indices.sort((a, b) => { return d[a] > d[b] ? -1 : d[a] < d[b] ? 1 : 0; });
    return indices;
};
export const getInterpolatedArray = (data: number[], fitCount: number) => {
    let newData = [];
    let springFactor = (data.length - 1) / (fitCount - 1);
    newData[0] = data[0];
    for (let i = 1; i < fitCount - 1; i++) {
        let tmp: number = i * springFactor;
        let before: number = +(Math.floor(tmp)).toFixed();
        let after: number = +(Math.ceil(tmp)).toFixed();
        let atPoint: number = tmp - before;
        newData[i] = linearInterpolate(data[before], data[after], atPoint);
    }
    newData[fitCount - 1] = data[data.length - 1];
    return newData;
};
export const linearInterpolate = (before: number, after: number, atPoint: number) => {
    return before + (after - before) * atPoint;
}
/**
 * 
 * @param lon number
 * @param lat number
 * @returns [lon, lat] 
 */
 export const coord3857To4326 = (lon: number, lat: number): number[] =>  {
    
    const e_value = 2.7182818284;
    const X = 20037508.34;
    
    const lat3857 = lon
    const long3857 = lon;
    
    //converting the longitute from epsg 3857 to 4326
    const long4326 = (long3857*180)/X;
    
    //converting the latitude from epsg 3857 to 4326 split in multiple lines for readability        
    let lat4326 = lat3857/(X / 180);
    const exponent = (Math.PI / 180) * lat4326;
    
    lat4326 = Math.atan(Math.pow(e_value, exponent));
    lat4326 = lat4326 / (Math.PI / 360); // Here is the fixed line
    lat4326 = lat4326 - 90;

    return [long4326, lat4326];
    
}
/**
 * 
 * @param lon number
 * @param lat number
 * @returns [lon, lat] 
 */
export const coord4326To3857 = (lon: number, lat: number): number[] =>  {
    const X = 20037508.34;
    let long3857 = (lon * X) / 180;

    let lat3857 = lat + 90;
    lat3857 = lat3857 * (Math.PI/360);
    lat3857 = Math.tan(lat3857);
    lat3857 = Math.log(lat3857);
    lat3857 = lat3857 / (Math.PI / 180);
    
    lat3857 = (lat3857 * X) / 180;

    return [long3857, lat3857];
}
export const shuffleArray = (array: any[]) => {
    
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        const temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

export const MercatorProjection = (longitude: number, latitude: number) => {

    // latitude    = 41.145556; // (φ)
    // longitude   = -73.995;   // (λ)

    const  mapWidth = 30559983.333; // 200
    const  mapHeight = 446; // 100

    // get x value
    const  x = (longitude + 180) * (mapWidth / 360);

    // convert from degrees to radians
    const  latRad = latitude * Math.PI / 180;

    // get y value
    const  mercN = Math.log(Math.tan((Math.PI / 4) + (latRad / 2)));
    const  y = (mapHeight / 2) - (mapWidth * mercN / (2 * Math.PI)) * -1;
    return [x, y];
}